//! The credits page: the scene's asset manifest, `asset_manifest.json` (format version 1, ADR-3013), one row per
//! asset with its source and license, shown in the demo and returned by `demo.credits`.
//!
//! ```json
//! { "version": 1,
//!   "assets": [ { "path": "heightfield.png", "title": "Example heightfield", "author": "Regia Engine",
//!                 "license": "LicenseRef-Regia-Sample", "source": "generated by showcase --write-example" } ] }
//! ```
//!
//! `path` is relative to the scene directory (`/` separators) and unique; `title`, `author`, `license` and
//! `source` are required and non-empty; `notes` is optional. The page also lists the scene's files that have no
//! row ([`unlisted_files`]), so a missing license is visible on screen. A scene without the file shows a note
//! instead of credits; a malformed file shows its error. The engine's own third-party notices are not repeated
//! here: the page points at `THIRD_PARTY_NOTICES.md`.

use std::collections::BTreeSet;
use std::path::Path;

use serde::{Deserialize, Serialize};
use serde_json::{Value, json};

/// The manifest's file name in the scene directory.
pub const MANIFEST_FILE: &str = "asset_manifest.json";
/// The format version this reader understands.
pub const MANIFEST_FORMAT_VERSION: u32 = 1;
/// The largest manifest read, bytes.
pub const MAX_MANIFEST_BYTES: u64 = 4 << 20;
/// The engine line the page always shows.
pub const ENGINE_LINE: &str =
    "Built with Regia Engine. Third-party software notices: THIRD_PARTY_NOTICES.md.";

/// One asset's credit.
#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct AssetCredit {
    /// The file, relative to the scene directory, `/` separators.
    pub path: String,
    /// What it is.
    pub title: String,
    /// Who made it.
    pub author: String,
    /// Its license (an SPDX id, or a `LicenseRef-` id).
    pub license: String,
    /// Where it came from.
    pub source: String,
    /// Anything else the credit must say.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub notes: Option<String>,
}

/// The `asset_manifest.json` document.
#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct AssetManifest {
    /// Format version ([`MANIFEST_FORMAT_VERSION`]).
    pub version: u32,
    /// One row per asset.
    pub assets: Vec<AssetCredit>,
}

impl AssetManifest {
    /// Parses and validates a manifest.
    ///
    /// # Errors
    /// A message naming the problem: not JSON, a newer version, an empty field, an absolute or `..` path, or a
    /// duplicate path.
    pub fn parse(text: &str) -> Result<Self, String> {
        let manifest: AssetManifest = serde_json::from_str(text).map_err(|e| e.to_string())?;
        if manifest.version != MANIFEST_FORMAT_VERSION {
            return Err(format!(
                "version {} is not {MANIFEST_FORMAT_VERSION} (this build reads version {MANIFEST_FORMAT_VERSION})",
                manifest.version
            ));
        }
        let mut seen = BTreeSet::new();
        for (index, asset) in manifest.assets.iter().enumerate() {
            for (field, value) in [
                ("path", &asset.path),
                ("title", &asset.title),
                ("author", &asset.author),
                ("license", &asset.license),
                ("source", &asset.source),
            ] {
                if value.trim().is_empty() {
                    return Err(format!("assets[{index}].{field} is empty"));
                }
            }
            let bad_path = asset.path.starts_with('/')
                || asset.path.contains('\\')
                || asset.path.split('/').any(|part| part.is_empty() || part == "..");
            if bad_path {
                return Err(format!(
                    "assets[{index}].path `{}` must be relative to the scene, with `/` and no `..`",
                    asset.path
                ));
            }
            if !seen.insert(asset.path.as_str()) {
                return Err(format!("assets[{index}].path `{}` is listed twice", asset.path));
            }
        }
        Ok(manifest)
    }
}

/// What the credits page shows.
#[derive(Clone, Debug, Default, PartialEq, Eq)]
pub struct Credits {
    /// The manifest, when the scene has a valid one.
    pub manifest: Option<AssetManifest>,
    /// Why the manifest is missing or unreadable.
    pub error: Option<String>,
    /// Scene files with no row (sorted).
    pub unlisted: Vec<String>,
}

impl Credits {
    /// Reads the manifest of `scene_dir` and lists the files it does not cover.
    #[must_use]
    pub fn load(scene_dir: &Path) -> Self {
        let path = scene_dir.join(MANIFEST_FILE);
        let read = std::fs::metadata(&path)
            .map_err(|e| format!("{}: {e}", path.display()))
            .and_then(|meta| {
                if meta.len() > MAX_MANIFEST_BYTES {
                    Err(format!(
                        "{}: larger than {MAX_MANIFEST_BYTES} bytes",
                        path.display()
                    ))
                } else {
                    std::fs::read_to_string(&path).map_err(|e| format!("{}: {e}", path.display()))
                }
            });
        let (manifest, error) = match read {
            Ok(text) => match AssetManifest::parse(&text) {
                Ok(m) => (Some(m), None),
                Err(e) => (None, Some(format!("{}: {e}", path.display()))),
            },
            Err(e) => (None, Some(e)),
        };
        let unlisted = manifest
            .as_ref()
            .map(|m| unlisted_files(scene_dir, m))
            .unwrap_or_default();
        Self {
            manifest,
            error,
            unlisted,
        }
    }

    /// The page's lines: the engine line, one line per asset, then the unlisted files or the error.
    #[must_use]
    pub fn lines(&self) -> Vec<String> {
        let mut lines = vec![ENGINE_LINE.to_owned()];
        match &self.manifest {
            Some(manifest) => {
                for a in &manifest.assets {
                    lines.push(format!(
                        "{}: {} ({}), {}. {}",
                        a.title, a.author, a.license, a.source, a.path
                    ));
                }
                if !self.unlisted.is_empty() {
                    lines.push(format!(
                        "No credit recorded for {} file(s): {}",
                        self.unlisted.len(),
                        self.unlisted.join(", ")
                    ));
                }
            }
            None => lines.push(format!(
                "No asset credits: {}",
                self.error.as_deref().unwrap_or("no manifest")
            )),
        }
        lines
    }

    /// The credits as JSON (`demo.credits`).
    #[must_use]
    pub fn to_json(&self) -> Value {
        json!({
            "engine": ENGINE_LINE,
            "manifest": MANIFEST_FILE,
            "format_version": self.manifest.as_ref().map(|m| m.version),
            "assets": self.manifest.as_ref().map(|m| m.assets.clone()).unwrap_or_default(),
            "unlisted": self.unlisted,
            "error": self.error,
        })
    }
}

/// Files under `scene_dir` (recursively, `/` separators) that the manifest has no row for. The manifest itself is
/// not an asset.
#[must_use]
pub fn unlisted_files(scene_dir: &Path, manifest: &AssetManifest) -> Vec<String> {
    let listed: BTreeSet<&str> = manifest.assets.iter().map(|a| a.path.as_str()).collect();
    let mut out = Vec::new();
    let mut stack = vec![scene_dir.to_path_buf()];
    while let Some(dir) = stack.pop() {
        let Ok(entries) = std::fs::read_dir(&dir) else {
            continue;
        };
        for entry in entries.flatten() {
            let path = entry.path();
            if path.is_dir() {
                stack.push(path);
                continue;
            }
            let Ok(relative) = path.strip_prefix(scene_dir) else {
                continue;
            };
            let name = relative
                .components()
                .map(|c| c.as_os_str().to_string_lossy().into_owned())
                .collect::<Vec<_>>()
                .join("/");
            if name != MANIFEST_FILE && !listed.contains(name.as_str()) {
                out.push(name);
            }
        }
    }
    out.sort();
    out
}

#[cfg(test)]
mod tests {
    use super::*;

    fn row(path: &str) -> Value {
        json!({ "path": path, "title": "t", "author": "a", "license": "CC0-1.0", "source": "s" })
    }

    #[test]
    fn manifests_validate_their_rows() {
        let ok = json!({ "version": 1, "assets": [row("a.png"), row("dir/b.ron")] }).to_string();
        assert_eq!(AssetManifest::parse(&ok).map(|m| m.assets.len()), Ok(2));
        for bad in [
            json!({ "version": 2, "assets": [] }),
            json!({ "version": 1, "assets": [row("a.png"), row("a.png")] }),
            json!({ "version": 1, "assets": [row("../x.png")] }),
            json!({ "version": 1, "assets": [row("/x.png")] }),
            json!({ "version": 1, "assets": [row("a//b.png")] }),
            json!({ "version": 1, "assets": [{ "path": "a", "title": "", "author": "a", "license": "x", "source": "s" }] }),
            json!({ "version": 1, "assets": [], "extra": 1 }),
        ] {
            assert!(AssetManifest::parse(&bad.to_string()).is_err(), "{bad}");
        }
        assert!(AssetManifest::parse("not json").is_err());
    }

    #[test]
    fn the_shipped_example_scene_credits_every_file() {
        let dir = Path::new(env!("CARGO_MANIFEST_DIR")).join("example_scene");
        let credits = Credits::load(&dir);
        assert_eq!(credits.error, None);
        assert_eq!(
            credits.unlisted,
            Vec::<String>::new(),
            "every example file has a credit row"
        );
        let manifest = credits.manifest.clone().unwrap_or(AssetManifest {
            version: 0,
            assets: Vec::new(),
        });
        for asset in &manifest.assets {
            assert!(dir.join(&asset.path).is_file(), "{} exists", asset.path);
        }
        assert!(credits.lines()[0].contains("Regia Engine"));
    }

    #[test]
    fn a_scene_without_a_manifest_says_so() {
        let dir = regia_test_utils::unique_temp_dir("showcase-credits-none");
        let credits = Credits::load(&dir);
        assert!(credits.manifest.is_none());
        assert!(credits.error.is_some());
        assert!(credits.lines()[1].starts_with("No asset credits"));
        assert_eq!(credits.to_json()["assets"], json!([]));
    }
}
